from app.services import users


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def _is_valid_email(value) -> bool:
    if not isinstance(value, str):
        return False
    email = value.strip()
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    if not local:
        return False
    if "." not in domain:
        return False
    return not (domain.startswith(".") or domain.endswith("."))


def handle_find_user_by_email(params: dict) -> tuple[int, dict]:
    raw = params.get("email")
    if not _is_valid_email(raw):
        return 400, {"error": "invalid email"}
    user = users.find_by_email(raw.strip())
    if user is None:
        return 404, {"error": "not found"}
    return 200, user
"}

